beforeExample:
class Example {
    void foo(Object obj) {
        if (obj != null && obj instanceof String) {
            System.out.println("It's a string");
        }
    }
}

afterExample:
class Example {
    void foo(Object obj) {
        if (obj instanceof String) {
            System.out.println("It's a string");
        }
    }
}

negativeExample:
class ExampleNegative {
    void foo(Object obj) {
        if (obj != null && obj.hashCode() > 0) { // Not an 'instanceof' check, should not match
            System.out.println("Not a string");
        }
        if (obj instanceof String && obj != null) { // Order is different, should not match
            System.out.println("Order is different");
        }
    }
}
